using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using Newtonsoft.Json.Linq;
using UnityEngine.TextCore.Text;

namespace Imoni.Editor
{
    /// <summary>Known UI glyphs are generated by Setup, before a screen can create another atlas at render time.</summary>
    internal static class ImoniFontWarmup
    {
        private const string Root = "Assets/Imoni";
        internal static bool PrepareUi(FontAsset asset, string assetName)
        {
            bool isDela = assetName == "DelaGothicOne SDF";
            if (!isDela && !assetName.StartsWith("ZenMaruGothic-", StringComparison.Ordinal)) return false;
            JObject config = JObject.Parse(File.ReadAllText(Root + "/Config/GameConfig.json"));
            var text = new StringBuilder();
            // Use source-controlled text rather than a previous play session's incidental cache.
            // Include all attributes so custom controls' labels are covered too, and all runtime
            // literals, including Core projections that supply labels and validation messages.
            foreach (string path in Directory.GetFiles(Root + "/Resources/UI", "*.uxml", SearchOption.AllDirectories))
                foreach (Match match in Regex.Matches(File.ReadAllText(path), "=\"([^\"]*)\""))
                    text.Append(match.Groups[1].Value);
            foreach (string path in Directory.GetFiles(Root + "/Scripts", "*.cs", SearchOption.AllDirectories))
                foreach (Match match in Regex.Matches(File.ReadAllText(path), "\"((?:\\\\.|[^\"\\\\])*)\""))
                    text.Append(Regex.Replace(match.Groups[1].Value, @"\\u([0-9a-fA-F]{4})",
                        escaped => ((char)Convert.ToUInt16(escaped.Groups[1].Value, 16)).ToString()));
            foreach (JValue value in config.Descendants().OfType<JValue>().Where(value => value.Type == JTokenType.String))
                text.Append(value.Value<string>());
            // The supplied Zen faces lack 秭; their prewarmed Dela fallback supplies it.
            // Dela lacks full-width ＋, used only by the Zen-font warehouse Small button.
            // These are verified cmap exceptions, not silent rejection of unknown UI glyphs.
            var codepoints = new SortedSet<uint>();
            string characters = text.ToString();
            for (int index = 0; index < characters.Length; index++)
            {
                uint point = (uint)char.ConvertToUtf32(characters, index);
                if (char.IsHighSurrogate(characters[index])) index++;
                if (point >= ' ' && (isDela ? point != 0xFF0B : point != 0x79ED)) codepoints.Add(point);
            }
            return AddMissing(asset, codepoints.ToArray());
        }

        private static bool AddMissing(FontAsset asset, uint[] codepoints)
        {
            asset.ReadFontAssetDefinition();
            uint[] additions = codepoints.Where(point => !asset.characterLookupTable.ContainsKey(point)).ToArray();
            if (additions.Length == 0) return false;
            bool populated = asset.TryAddCharacters(additions, out _, includeFontFeatures: true);
            // Unity 6 returns the original input in its missing array when every glyph already
            // exists, even though the call succeeds. Verify the resulting table for repeat Setup.
            uint[] missing = codepoints.Where(point => !asset.characterLookupTable.ContainsKey(point)).ToArray();
            if (missing.Length > 0)
                throw new InvalidOperationException("UI font warmup is missing glyphs (TryAddCharacters=" + populated + "): " + string.Join(", ", missing.Select(point => "U+" + point.ToString("X4"))));
            // Keep Dynamic: names entered by the player remain unrestricted by this known-glyph set.
            return true;
        }
    }
}
